ALTER TABLE public.profiles ADD COLUMN allow_messages boolean NOT NULL DEFAULT true;
ALTER TABLE public.profiles ADD COLUMN email_notifications boolean NOT NULL DEFAULT true;
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), initiator_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), declined_at timestamptz, CHECK(initiator_id <> recipient_id));
GRANT SELECT ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX conversation_pair ON public.conversations (least(initiator_id,recipient_id), greatest(initiator_id,recipient_id));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, body text NOT NULL CHECK(char_length(btrim(body)) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE INDEX messages_conversation_time ON public.messages(conversation_id,created_at);
CREATE TABLE public.conversation_reads (conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(conversation_id,user_id));
GRANT SELECT ON public.conversation_reads TO authenticated; GRANT ALL ON public.conversation_reads TO service_role;
ALTER TABLE public.conversation_reads ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_blocks (blocker_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, blocked_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
GRANT SELECT ON public.user_blocks TO authenticated; GRANT ALL ON public.user_blocks TO service_role;
ALTER TABLE public.user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY blocks_own_read ON public.user_blocks FOR SELECT TO authenticated USING(blocker_id=auth.uid());
CREATE TABLE public.conversation_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, reporter_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, message_id uuid REFERENCES public.messages(id) ON DELETE CASCADE, reason text NOT NULL CHECK(reason IN ('spam','abuse','fraud','other')), details text NOT NULL DEFAULT '' CHECK(char_length(details)<=500), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conversation_reports TO authenticated; GRANT ALL ON public.conversation_reports TO service_role;
ALTER TABLE public.conversation_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_read ON public.conversation_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.site_bans (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, admin_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_bans TO authenticated; GRANT ALL ON public.site_bans TO service_role;
ALTER TABLE public.site_bans ENABLE ROW LEVEL SECURITY;
CREATE POLICY bans_read ON public.site_bans FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.participant_activity (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, last_seen_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.participant_activity TO authenticated; GRANT ALL ON public.participant_activity TO service_role;
ALTER TABLE public.participant_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_own_read ON public.participant_activity FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.can_read_conversation(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=_id AND (auth.uid() IN (c.initiator_id,c.recipient_id) OR (public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.conversation_reports r WHERE r.conversation_id=c.id)))); $$;
REVOKE ALL ON FUNCTION public.can_read_conversation(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_read_conversation(uuid) TO authenticated,service_role;
CREATE POLICY conversations_read ON public.conversations FOR SELECT TO authenticated USING(public.can_read_conversation(id));
CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(public.can_read_conversation(conversation_id));
CREATE POLICY reads_read ON public.conversation_reads FOR SELECT TO authenticated USING(public.can_read_conversation(conversation_id));
CREATE FUNCTION public.can_contact_participant(_target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_target AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_target AND p.show_on_map AND p.allow_messages) AND NOT EXISTS(SELECT 1 FROM public.site_bans b WHERE b.user_id IN(auth.uid(),_target)) AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE (b.blocker_id=auth.uid() AND b.blocked_id=_target) OR (b.blocker_id=_target AND b.blocked_id=auth.uid())); $$;
REVOKE ALL ON FUNCTION public.can_contact_participant(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_contact_participant(uuid) TO authenticated,service_role;
CREATE FUNCTION public.message_contacts(_points uuid[]) RETURNS TABLE(point_id uuid,user_id uuid,display_name text,family_name text,city text,avatar_path text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,p.id,p.display_name,p.family_name,p.city,p.avatar_path FROM public.map_points m JOIN public.profiles p ON p.id=m.user_id WHERE m.id=ANY(_points) AND m.status='approved' AND m.consent_to_publish AND public.can_contact_participant(p.id); $$;
REVOKE ALL ON FUNCTION public.message_contacts(uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.message_contacts(uuid[]) TO authenticated,service_role;
CREATE FUNCTION public.messaging_inbox() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Войдите в аккаунт'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'initiator_id',c.initiator_id,'recipient_id',c.recipient_id,'status',c.status,'updated_at',c.updated_at,'declined_at',c.declined_at,'peer_id',p.id,'name',p.display_name,'family',p.family_name,'city',p.city,'avatar_path',p.avatar_path,'blocked',EXISTS(SELECT 1 FROM public.user_blocks b WHERE (b.blocker_id=auth.uid() AND b.blocked_id=p.id) OR (b.blocker_id=p.id AND b.blocked_id=auth.uid())),'banned',EXISTS(SELECT 1 FROM public.site_bans b WHERE b.user_id IN(auth.uid(),p.id)),'last_body',(SELECT m.body FROM public.messages m WHERE m.conversation_id=c.id ORDER BY m.created_at DESC LIMIT 1),'unread',(SELECT count(*) FROM public.messages m WHERE m.conversation_id=c.id AND m.sender_id<>auth.uid() AND m.created_at>coalesce((SELECT r.read_at FROM public.conversation_reads r WHERE r.conversation_id=c.id AND r.user_id=auth.uid()),'epoch'::timestamptz))) ORDER BY c.updated_at DESC) FROM public.conversations c JOIN public.profiles p ON p.id=CASE WHEN c.initiator_id=auth.uid() THEN c.recipient_id ELSE c.initiator_id END WHERE auth.uid() IN(c.initiator_id,c.recipient_id)),'[]'::jsonb); END; $$;
REVOKE ALL ON FUNCTION public.messaging_inbox() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.messaging_inbox() TO authenticated,service_role;
CREATE FUNCTION public.start_conversation(_target uuid,_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.conversations; cid uuid; BEGIN IF NOT public.can_contact_participant(_target) THEN RAISE EXCEPTION 'Переписка с этим участником недоступна'; END IF; IF char_length(btrim(_body)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Сообщение: от 1 до 2000 символов'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(least(auth.uid(),_target)::text||greatest(auth.uid(),_target)::text,0)); SELECT * INTO c FROM public.conversations WHERE least(initiator_id,recipient_id)=least(auth.uid(),_target) AND greatest(initiator_id,recipient_id)=greatest(auth.uid(),_target) FOR UPDATE; IF FOUND THEN IF c.status='declined' AND c.declined_at<=now()-interval '30 days' THEN UPDATE public.conversations SET initiator_id=auth.uid(),recipient_id=_target,status='pending',declined_at=NULL,updated_at=now() WHERE id=c.id; cid:=c.id; ELSE RAISE EXCEPTION 'Запрос уже отправлен или повторная отправка недоступна 30 дней'; END IF; ELSE INSERT INTO public.conversations(initiator_id,recipient_id) VALUES(auth.uid(),_target) RETURNING id INTO cid; END IF; INSERT INTO public.messages(conversation_id,sender_id,body) VALUES(cid,auth.uid(),btrim(_body)); RETURN cid; END; $$;
REVOKE ALL ON FUNCTION public.start_conversation(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.start_conversation(uuid,text) TO authenticated;
CREATE FUNCTION public.send_chat_message(_conversation uuid,_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.conversations; mid uuid; BEGIN SELECT * INTO c FROM public.conversations WHERE id=_conversation FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR auth.uid() NOT IN(c.initiator_id,c.recipient_id) THEN RAISE EXCEPTION 'Диалог недоступен'; END IF; IF c.status<>'accepted' THEN RAISE EXCEPTION 'Дождитесь принятия запроса'; END IF; IF EXISTS(SELECT 1 FROM public.site_bans WHERE user_id IN(c.initiator_id,c.recipient_id)) OR EXISTS(SELECT 1 FROM public.user_blocks WHERE (blocker_id=c.initiator_id AND blocked_id=c.recipient_id) OR (blocker_id=c.recipient_id AND blocked_id=c.initiator_id)) THEN RAISE EXCEPTION 'Переписка заблокирована'; END IF; IF char_length(btrim(_body)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Сообщение: от 1 до 2000 символов'; END IF; INSERT INTO public.messages(conversation_id,sender_id,body) VALUES(c.id,auth.uid(),btrim(_body)) RETURNING id INTO mid; UPDATE public.conversations SET updated_at=now() WHERE id=c.id; RETURN mid; END; $$;
REVOKE ALL ON FUNCTION public.send_chat_message(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.send_chat_message(uuid,text) TO authenticated;
CREATE FUNCTION public.decide_conversation(_conversation uuid,_decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _decision NOT IN('accepted','declined') THEN RAISE EXCEPTION 'Некорректное решение'; END IF; UPDATE public.conversations SET status=_decision,updated_at=now(),declined_at=CASE WHEN _decision='declined' THEN now() ELSE NULL END WHERE id=_conversation AND recipient_id=auth.uid() AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Запрос недоступен'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.decide_conversation(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_conversation(uuid,text) TO authenticated;
CREATE FUNCTION public.mark_conversation_read(_conversation uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.conversations WHERE id=_conversation AND auth.uid() IN(initiator_id,recipient_id)) THEN RAISE EXCEPTION 'Диалог недоступен'; END IF; INSERT INTO public.conversation_reads(conversation_id,user_id) VALUES(_conversation,auth.uid()) ON CONFLICT(conversation_id,user_id) DO UPDATE SET read_at=now(); END; $$;
REVOKE ALL ON FUNCTION public.mark_conversation_read(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mark_conversation_read(uuid) TO authenticated;
CREATE FUNCTION public.set_participant_block(_target uuid,_blocked boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR auth.uid()=_target THEN RAISE EXCEPTION 'Недопустимый участник'; END IF; IF _blocked THEN INSERT INTO public.user_blocks(blocker_id,blocked_id) VALUES(auth.uid(),_target) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.user_blocks WHERE blocker_id=auth.uid() AND blocked_id=_target; END IF; END; $$;
REVOKE ALL ON FUNCTION public.set_participant_block(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_participant_block(uuid,boolean) TO authenticated;
CREATE FUNCTION public.blocked_participants() RETURNS TABLE(user_id uuid,display_name text,family_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name,p.family_name FROM public.user_blocks b JOIN public.profiles p ON p.id=b.blocked_id WHERE b.blocker_id=auth.uid(); $$;
REVOKE ALL ON FUNCTION public.blocked_participants() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.blocked_participants() TO authenticated;
CREATE FUNCTION public.report_conversation(_conversation uuid,_message uuid,_reason text,_details text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.conversations WHERE id=_conversation AND auth.uid() IN(initiator_id,recipient_id)) THEN RAISE EXCEPTION 'Диалог недоступен'; END IF; IF _message IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.messages WHERE id=_message AND conversation_id=_conversation) THEN RAISE EXCEPTION 'Сообщение недоступно'; END IF; INSERT INTO public.conversation_reports(conversation_id,reporter_id,message_id,reason,details) VALUES(_conversation,auth.uid(),_message,_reason,_details) RETURNING id INTO rid; RETURN rid; END; $$;
REVOKE ALL ON FUNCTION public.report_conversation(uuid,uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.report_conversation(uuid,uuid,text,text) TO authenticated;
CREATE FUNCTION public.review_conversation_report(_report uuid,_ban boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Нет прав администратора'; END IF; SELECT CASE WHEN c.initiator_id=r.reporter_id THEN c.recipient_id ELSE c.initiator_id END INTO target FROM public.conversation_reports r JOIN public.conversations c ON c.id=r.conversation_id WHERE r.id=_report; IF target IS NULL THEN RAISE EXCEPTION 'Жалоба не найдена'; END IF; IF _ban THEN IF public.has_role(target,'admin') THEN RAISE EXCEPTION 'Нельзя заблокировать администратора'; END IF; INSERT INTO public.site_bans(user_id,admin_id) VALUES(target,auth.uid()) ON CONFLICT DO NOTHING; END IF; UPDATE public.conversation_reports SET status='closed' WHERE id=_report; END; $$;
REVOKE ALL ON FUNCTION public.review_conversation_report(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_conversation_report(uuid,boolean) TO authenticated;
CREATE FUNCTION public.touch_participant_activity() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.participant_activity(user_id) VALUES(auth.uid()) ON CONFLICT(user_id) DO UPDATE SET last_seen_at=now(); END IF; END; $$;
REVOKE ALL ON FUNCTION public.touch_participant_activity() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.touch_participant_activity() TO authenticated;
CREATE FUNCTION public.reject_banned_point() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.user_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.site_bans WHERE user_id=NEW.user_id) THEN RAISE EXCEPTION 'Аккаунт заблокирован на сайте'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER map_points_ban_guard BEFORE INSERT ON public.map_points FOR EACH ROW EXECUTE FUNCTION public.reject_banned_point();
CREATE TRIGGER participant_marks_ban_guard BEFORE INSERT ON public.participant_marks FOR EACH ROW EXECUTE FUNCTION public.reject_banned_point();
ALTER PUBLICATION supabase_realtime ADD TABLE public.conversations,public.messages,public.conversation_reads;
